Describe 'Show-InvocationTable' {
    It 'returns valid JSON for provided args' {
        . "${PSScriptRoot.Replace('Prismata\\tests\\primitives','Prismata\\Projects\\Tooling\\primitives')}\show-invocation-table.ps1"
        $argsHash = [ordered]@{ a = 1; b = 'two'; long = ('x' * 150) }
        $json = Show-InvocationTable -Args $argsHash -Format json
        $obj = $json | ConvertFrom-Json
        $obj | Should -Not -BeNullOrEmpty
        ($obj | Where-Object { $_.Name -eq 'a' }).Value | Should -Be '1'
    }
}
